package cn.haiduo;
import cn.haiduo.inventory.InventoryService;
import cn.haiduo.audit.Audit;
import cn.haiduo.platform.*;
import java.util.*;
import java.math.BigDecimal;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
@Service public class SyncProcessor {
 private final JdbcTemplate db;private final ShopifyAuthorization shopify;private final InventoryService inventory;
 public SyncProcessor(JdbcTemplate db,ShopifyAuthorization shopify,InventoryService inventory){this.db=db;this.shopify=shopify;this.inventory=inventory;}
 public void process(UUID tenant,String kind,String target)throws Exception{UUID store;String orderGid=null;UUID inbox=null;if(kind.equals("SHOPIFY_WEBHOOK")){inbox=UUID.fromString(target);var row=db.queryForMap("select store_id,order_gid from webhook_inbox where tenant_id=? and id=?",tenant,inbox);store=(UUID)row.get("store_id");orderGid=(String)row.get("order_gid");}else store=UUID.fromString(target);db.queryForObject("select id from store where tenant_id=? and id=? for update",UUID.class,tenant,store);var source=db.queryForMap("select name,platform,connection_status from store where tenant_id=? and id=?",tenant,store);boolean mock=source.get("platform").equals("MOCK");PlatformConnector connector=mock?new MockConnector():shopify.connector(tenant,store);if(!mock&&!source.get("connection_status").equals("CONNECTED"))throw new IllegalStateException("Store is disconnected");var settings=db.query("select warehouse_id from store_sync_settings where tenant_id=? and store_id=? for update",(rs,n)->rs.getObject(1,UUID.class),tenant,store);UUID warehouse=settings.isEmpty()?UUID.fromString("00000000-0000-0000-0000-000000000001"):settings.getFirst();if(!mock&&settings.isEmpty())throw new IllegalStateException("Store sync settings required");List<PlatformConnector.Order> orders=orderGid==null?connector.orders():connector.order(orderGid).map(List::of).orElse(List.of());for(var order:orders)upsert(tenant,store,(String)source.get("name"),warehouse,mock,order);if(inbox!=null)db.update("update webhook_inbox set status='PROCESSED' where tenant_id=? and id=?",tenant,inbox);}
 void upsert(UUID tenant,UUID store,String storeName,UUID warehouse,boolean mock,PlatformConnector.Order order){Map<UUID,Integer> quantities=new TreeMap<>();for(var item:order.items()){var mapped=db.query("select sku_id from store_listing where tenant_id=? and store_id=? and platform_product_id=?",(rs,n)->rs.getObject(1,UUID.class),tenant,store,item.platformVariantId());if(mapped.isEmpty())mapped=db.query("select id from sku where tenant_id=? and code=?",(rs,n)->rs.getObject(1,UUID.class),tenant,item.sku());if(mapped.isEmpty())throw new IllegalStateException("Platform SKU mapping missing");quantities.merge(mapped.getFirst(),item.quantity(),Math::addExact);}var existing=db.queryForList("select id,status,currency,source_updated_at from sales_order where tenant_id=? and store=? and external_id=? for update",tenant,storeName,order.externalId());if(!existing.isEmpty()){var row=existing.getFirst();UUID id=(UUID)row.get("id");var version=(java.sql.Timestamp)row.get("source_updated_at");if(version!=null&&!order.updatedAt().isAfter(version.toInstant()))return;if(!row.get("currency").equals(order.currency()))throw new IllegalStateException("Order currency changed; manual review required");Map<UUID,Integer> old=new TreeMap<>();for(var line:db.queryForList("select sku_id,quantity from order_item where tenant_id=? and order_id=?",tenant,id))old.put((UUID)line.get("sku_id"),(Integer)line.get("quantity"));boolean changed=!old.equals(quantities);if(changed&&row.get("status").equals("NEW")){Map<UUID,BigDecimal> costs=new HashMap<>();for(var line:db.queryForList("select sku_id,unit_cost_cny from order_item where tenant_id=? and order_id=?",tenant,id))costs.put((UUID)line.get("sku_id"),(BigDecimal)line.get("unit_cost_cny"));db.update("delete from order_item where tenant_id=? and order_id=?",tenant,id);for(var line:quantities.entrySet()){BigDecimal cost=costs.containsKey(line.getKey())?costs.get(line.getKey()):db.queryForObject("select cost from sku where tenant_id=? and id=?",BigDecimal.class,tenant,line.getKey());db.update("insert into order_item(tenant_id,order_id,sku_id,quantity,unit_cost_cny) values(?,?,?,?,?)",tenant,id,line.getKey(),line.getValue(),cost);}changed=false;}boolean external=order.fulfillment().equals("FULFILLED");boolean review=!Set.of("UNKNOWN","UNFULFILLED","OPEN","FULFILLED").contains(order.fulfillment())||changed||external&&row.get("status").equals("RESERVED")||order.cancelled()&&row.get("status").equals("SHIPPED");db.update("update sales_order set net=?,payment_status=?,refund_status=?,source_updated_at=?,sync_review_required=?,platform_fulfillment_status=? where tenant_id=? and id=?",order.net(),order.payment(),order.refund(),java.sql.Timestamp.from(order.updatedAt()),review,order.fulfillment(),tenant,id);if(external&&row.get("status").equals("NEW"))db.update("update sales_order set status='SHIPPED',externally_fulfilled=true where tenant_id=? and id=?",tenant,id);if(!external&&order.cancelled()&&Set.of("NEW","RESERVED").contains(row.get("status")))inventory.transition(tenant,id,"cancel");new Audit(db).record(tenant,"system","ORDER_SYNC_UPDATE",id);return;}
  BigDecimal rate;String rateSource;java.sql.Timestamp effective;if(order.currency().equals("CNY")){rate=BigDecimal.ONE;rateSource="原币CNY";effective=java.sql.Timestamp.from(order.updatedAt());}else if(mock){rate=new BigDecimal("7.2");rateSource="MOCK固定演示汇率";effective=java.sql.Timestamp.from(order.updatedAt());}else{var rates=db.queryForList("select rate,source,effective_at from store_exchange_rate where tenant_id=? and store_id=? and currency=?",tenant,store,order.currency());if(rates.isEmpty())throw new IllegalStateException("Configured currency rate missing");rate=(BigDecimal)rates.getFirst().get("rate");rateSource=(String)rates.getFirst().get("source");effective=(java.sql.Timestamp)rates.getFirst().get("effective_at");}UUID id=UUID.randomUUID();int inserted=db.update("insert into sales_order(id,tenant_id,store,external_id,net,rate,currency,rate_source,rate_at,warehouse_id,payment_status,refund_status,source_updated_at) values(?,?,?,?,?,?,?,?,?,?,?,?,?) on conflict(tenant_id,store,external_id) do nothing",id,tenant,storeName,order.externalId(),order.net(),rate,order.currency(),rateSource,effective,warehouse,order.payment(),order.refund(),java.sql.Timestamp.from(order.updatedAt()));if(inserted==0)return;if(!Set.of("UNKNOWN","UNFULFILLED","OPEN","FULFILLED").contains(order.fulfillment()))db.update("update sales_order set sync_review_required=true where tenant_id=? and id=?",tenant,id);for(var line:quantities.entrySet())db.update("insert into order_item(tenant_id,order_id,sku_id,quantity,unit_cost_cny) select ?,?,?,?,cost from sku where tenant_id=? and id=?",tenant,id,line.getKey(),line.getValue(),tenant,line.getKey());db.update("update sales_order set platform_fulfillment_status=? where tenant_id=? and id=?",order.fulfillment(),tenant,id);if(order.fulfillment().equals("FULFILLED"))db.update("update sales_order set status='SHIPPED',externally_fulfilled=true,sync_review_required=? where tenant_id=? and id=?",order.cancelled(),tenant,id);else if(order.cancelled())inventory.transition(tenant,id,"cancel");new Audit(db).record(tenant,"system","ORDER_SYNC_CREATE",id);
 }
}
